CREATE OR REPLACE TABLE stg_customers AS SELECT * FROM read_csv_auto('{{RAW}}/olist_customers_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_orders AS SELECT order_id, customer_id, order_status, CAST(order_purchase_timestamp AS TIMESTAMP) order_purchase_timestamp, CAST(order_approved_at AS TIMESTAMP) order_approved_at, CAST(order_delivered_carrier_date AS TIMESTAMP) order_delivered_carrier_date, CAST(order_delivered_customer_date AS TIMESTAMP) order_delivered_customer_date, CAST(order_estimated_delivery_date AS TIMESTAMP) order_estimated_delivery_date FROM read_csv_auto('{{RAW}}/olist_orders_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_order_items AS SELECT order_id, order_item_id, product_id, seller_id, CAST(shipping_limit_date AS TIMESTAMP) shipping_limit_date, CAST(price AS DECIMAL(18,2)) price, CAST(freight_value AS DECIMAL(18,2)) freight_value FROM read_csv_auto('{{RAW}}/olist_order_items_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_payments AS SELECT order_id, payment_sequential, payment_type, payment_installments, CAST(payment_value AS DECIMAL(18,2)) payment_value FROM read_csv_auto('{{RAW}}/olist_order_payments_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_reviews AS SELECT review_id, order_id, review_score, review_comment_title, review_comment_message, CAST(review_creation_date AS TIMESTAMP) review_creation_date, CAST(review_answer_timestamp AS TIMESTAMP) review_answer_timestamp FROM read_csv_auto('{{RAW}}/olist_order_reviews_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_products AS SELECT * FROM read_csv_auto('{{RAW}}/olist_products_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_sellers AS SELECT * FROM read_csv_auto('{{RAW}}/olist_sellers_dataset.csv', header=true);
CREATE OR REPLACE TABLE stg_category_translation AS SELECT * FROM read_csv_auto('{{RAW}}/product_category_name_translation.csv', header=true);
